import {supply,protocols,series,change,json,vaults} from './data.mjs';
const $=id=>document.getElementById(id), money=n=>Number.isFinite(n)?'$'+Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(n):'—', full=n=>Number.isFinite(n)?'$'+Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(n):'—';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=t=>new Date(t*1000).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
let state={supply:[],tvl:[],protocols:null,vaults:null},metric='supply',days=30,view='protocols',expanded=false,busy=false;
function selected(id,key,value){for(const b of $(id).querySelectorAll('button')){const on=b.dataset[key]===String(value);b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on)}}
function chart(){const all=state[metric]||[],end=all.at(-1)?.date||0,pts=days?all.filter(p=>p.date>=end-(days-1)*86400):all;const last=pts.at(-1);$('chart-value').textContent=money(last?.value);const delta=change(last?.value,pts[0]?.value);$('chart-delta').textContent=pts.length>1&&delta!==null?(delta>=0?'+':'')+delta.toFixed(2)+'% in period':'';$('chart-date').textContent=last?'Latest indexed observation · '+date(last.date)+' UTC':'History unavailable';$('chart-start').textContent=pts.length?date(pts[0].date):'';$('chart-end').textContent=last?date(last.date):'';if(pts.length<2){$('chart').innerHTML='<p style="padding:70px 0;text-align:center">'+(last?'Not enough observations to draw a trend.':'Historical source unavailable. Use Refresh data to retry.')+'</p>';return}const w=1000,h=210,pad=18,plotW=920,min=Math.min(...pts.map(p=>p.value))*.92,max=Math.max(...pts.map(p=>p.value))*1.04,span=max-min||1,x=p=>(p.date-pts[0].date)/(last.date-pts[0].date)*plotW,y=p=>h-pad-(p.value-min)/span*(h-pad*2);const path=pts.map((p,i)=>(i?'L':'M')+x(p).toFixed(2)+','+y(p).toFixed(2)).join(' ');let grid='';for(let i=0;i<4;i++){const yy=pad+i*(h-pad*2)/3,val=max-i*span/3;grid+='<line x1="0" y1="'+yy+'" x2="'+plotW+'" y2="'+yy+'" stroke="#edf0e8" stroke-dasharray="3 5"/><text x="945" y="'+(yy+3)+'" fill="#919b89" font-size="10">'+money(val)+'</text>'}$('chart').innerHTML='<svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="'+esc(metric==='supply'?'USDC circulating supply':'DeFi TVL')+' from '+date(pts[0].date)+' to '+date(last.date)+'"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b9d692" stop-opacity=".35"/><stop offset="1" stop-color="#b9d692" stop-opacity="0"/></linearGradient></defs>'+grid+'<path d="'+path+' L '+plotW+','+h+' L 0,'+h+' Z" fill="url(#fill)"/><path d="'+path+'" fill="none" stroke="#5b7f41" stroke-width="2.5" stroke-linejoin="round"/>'+pts.map(p=>'<circle cx="'+x(p)+'" cy="'+y(p)+'" r="6" fill="transparent"><title>'+date(p.date)+' UTC · '+full(p.value)+'</title></circle>').join('')+'<circle cx="'+x(last)+'" cy="'+y(last)+'" r="4" fill="#5b7f41" stroke="white" stroke-width="2"/></svg>'}
function table(){const isVault=view==='vaults',rows=state[view],q=$('search').value.toLowerCase();$('table-head').innerHTML='<tr><th>#</th><th>'+(isVault?'VAULT / CONTRACT':'PROTOCOL')+'</th><th>'+(isVault?'ASSET':'CATEGORY')+'</th><th class="num">'+(isVault?'VAULT ASSETS':'ARC TVL')+'</th><th class="num">'+(isVault?'EXPLORER':'% OF CHAIN TVL')+'</th></tr>';$('table-notice').textContent=isVault?'Morpho V2 · indexed vaults ≥ $1,000 by default. Vault assets overlap with protocol TVL; never add these to the headline.':'Arc-only balances. “Overlap” flags curators and yield layers. Rows are not summed into the chain total.';if(!rows){$('table-body').innerHTML='<tr><td colspan="5">Source unavailable or loading. Refresh to retry.</td></tr>';$('table-count').textContent='Unavailable';$('show-all').hidden=true;return}let filtered=rows.filter(r=>(r.name+' '+(r.category||r.asset?.symbol)+' '+(r.address||'')).toLowerCase().includes(q));if(isVault&&!expanded&&!q)filtered=filtered.filter(v=>v.totalAssetsUsd>=1000);const visible=expanded||q?filtered:filtered.slice(0,10);$('table-count').textContent=visible.length+' / '+rows.length+' indexed';const total=state.chainTvl;$('table-body').innerHTML=visible.map((r,i)=>{const value=isVault?r.totalAssetsUsd:r.tvl,url=isVault?'https://explorer.arc.io/address/'+r.address:'https://defillama.com/protocol/'+encodeURIComponent(r.slug),share=Number.isFinite(total)&&total>0?value/total*100:null;return '<tr><td class="rank">'+(i+1)+'</td><td><a class="protocol" href="'+esc(url)+'" target="_blank" rel="noopener"><span class="avatar">'+esc((r.name||'V').slice(0,2))+'</span><span><b>'+esc(r.name||'Unnamed vault')+'</b>'+(r.overlap?'<span class="overlap">Overlap</span>':'')+(isVault?'<small style="display:block;color:#8b9585;font-size:10px;margin-top:4px">'+r.address.slice(0,8)+'…'+r.address.slice(-6)+'</small>':'')+'</span></a></td><td><span class="pill">'+esc(isVault?r.asset.symbol:r.category)+'</span></td><td class="num" title="'+full(value)+'"><b>'+money(value)+'</b></td><td class="num">'+(isVault?'<a href="'+esc(url)+'" target="_blank" rel="noopener" aria-label="View '+esc(r.name)+' contract">View contract ↗</a>':share===null?'—':'<span class="share"><span style="width:'+Math.min(100,share)+'%"></span></span>'+share.toFixed(2)+'%')+'</td></tr>'}).join('')||'<tr><td colspan="5">No matching results.</td></tr>';$('show-all').hidden=!!q||(!expanded&&rows.length<=visible.length);$('show-all').textContent=expanded?'Show fewer ↑':isVault?'Show all indexed vaults, including balances below $1,000 ↓':'Show all '+rows.length+' deployments ↓'}
async function load(){if(busy)return;busy=true;$('refresh').disabled=true;$('refresh-status').textContent='Refreshing sources…';let failures=[];const tasks=[['USDC history',async()=>{state.supply=series(await json('https://stablecoins.llama.fi/stablecoincharts/Arc?stablecoin=2'));if(!state.supply.length)throw Error('No history')}],['TVL history',async()=>{state.tvl=(await json('https://api.llama.fi/v2/historicalChainTvl/Arc')).filter(p=>Number.isFinite(p.tvl)).map(p=>({date:Number(p.date),value:p.tvl}));if(!state.tvl.length)throw Error('No history')}],['TVL',async()=>{const c=(await json('https://api.llama.fi/v2/chains')).find(p=>p.name==='Arc');if(!Number.isFinite(c?.tvl))throw Error('No Arc TVL');state.chainTvl=c.tvl;$('tvl').textContent=money(c.tvl);$('tvl').title=full(c.tvl);$('tvl-note').textContent='DefiLlama · fetched '+new Date().toLocaleTimeString();$('tvl-note').classList.remove('error')}],['Protocols',async()=>{state.protocols=protocols(await json('https://api.llama.fi/protocols'));if(!state.protocols.length)throw Error('No Arc protocols');$('coverage').textContent=state.protocols.length;$('coverage-note').textContent='Indexed deployments, including overlapping curators'}],['Vaults',async()=>{state.vaults=await vaults()}],['RPC',async()=>{const s=await supply();state.liveSupply=s;$('supply').textContent=money(s.value);$('supply').title=full(s.value)+' USDC';$('supply-note').textContent='Live RPC · block '+s.block.toLocaleString();$('supply-note').classList.remove('error')}]];
await Promise.all(tasks.map(async([name,fn])=>{try{await fn()}catch(e){failures.push(name);console.warn(name,e.message);if(name==='TVL'){$('tvl-note').textContent=state.chainTvl?'Stale · refresh failed':'Unavailable · refresh failed';$('tvl-note').classList.add('error')}if(name==='Protocols'){$('coverage-note').textContent='Protocol refresh failed';state.protocols=null}if(name==='Vaults')state.vaults=null;if(name==='USDC history')state.supply=[];if(name==='TVL history')state.tvl=[]}finally{chart();table()}}));if(failures.includes('RPC')){const fallback=state.supply.at(-1);$('supply').textContent=money(fallback?.value);$('supply-note').textContent=fallback?'Indexed fallback · '+date(fallback.date)+' UTC · RPC unavailable':'Supply unavailable · RPC and index failed';$('supply-note').classList.add('error');$('supply').title=fallback?full(fallback.value)+' USDC (indexed)':'Unavailable'}$('refresh-status').textContent=failures.length?'Partial data · '+failures.join(', ')+' unavailable':'Updated '+new Date().toLocaleTimeString()+' · refreshes every 5m';$('refresh-status').classList.toggle('error',!!failures.length);$('refresh').disabled=false;busy=false;chart();table()}
$('refresh').onclick=load;$('search').oninput=table;$('show-all').onclick=()=>{expanded=!expanded;table()};$('metric-toggle').onclick=e=>{if(!e.target.dataset.metric)return;metric=e.target.dataset.metric;selected('metric-toggle','metric',metric);chart()};$('range-toggle').onclick=e=>{if(e.target.dataset.days===undefined)return;days=Number(e.target.dataset.days);selected('range-toggle','days',days);chart()};$('table-toggle').onclick=e=>{if(!e.target.dataset.view)return;view=e.target.dataset.view;expanded=false;$('search').value='';$('search').placeholder=view==='vaults'?'Search vaults or addresses…':'Search protocols…';selected('table-toggle','view',view);table()};load();setInterval(load,300000);
